def check():
    from sol import flatten_nested

    assert flatten_nested({'a': {'b': 1}}) == {'a.b': 1}
    assert flatten_nested({'a': [10, 20]}) == {'a[0]': 10, 'a[1]': 20}
    assert flatten_nested({'a': {'b': [1]}}) == {'a.b[0]': 1}
    assert flatten_nested({'a': {'b': 1}, 'c': 2}) == {'a.b': 1, 'c': 2}
    assert flatten_nested({'a': {'b': 1}, 'c': [10, 20]}) == {'a.b': 1, 'c[0]': 10, 'c[1]': 20}
    assert flatten_nested({'a': {'b': 1}, 'c': [10, 20], 'd': {'e': {'f': [3, 4]}}}) == {'a.b': 1, 'c[0]': 10, 'c[1]': 20, 'd.e.f[0]': 3, 'd.e.f[1]': 4}
    assert flatten_nested({'a': None, 'b': {'c': 1}}) == {'b.c': 1}
    assert flatten_nested({'a': [None, 10, 20], 'b': {'c': 1}}) == {'b.c': 1, 'a[1]': 10, 'a[2]': 20}
