    from sol import parse_pairs

    assert parse_pairs("a=b;c=d") == {"a": "b", "c": "d"}
    assert parse_pairs("a='b=c';d=e") == {"a": "b=c", "d": "e"}
    assert parse_pairs("a='b=c'; d='e=f';g=h") == {"a": "b=c", "d": "e=f", "g": "h"}
    assert parse_pairs("a='b=c'; d='e=f'; g='h=i';j=k") == {"a": "b=c", "d": "e=f", "g": "h=i", "j": "k"}
    assert parse_pairs("a='b=c'; d='e=f'; g='h=i'; j='k=l';m=n") == {"a": "b=c", "d": "e=f", "g": "h=i", "j": "k=l", "m": "n"}
    assert parse_pairs("a='b=c'; d='e=f'; g='h=i'; j='k=l'; m='n;o';p=q") == {"a": "b=c", "d": "e=f", "g": "h=i", "j": "k=l", "m": "n;o", "p": "q"}
    assert parse_pairs("a='b=c'; d='e=f'; g='h=i'; j='k=l'; m='n;o'; p='q=r';s=t") == {"a": "b=c", "d": "e=f", "g": "h=i", "j": "k=l", "m": "n;o", "p": "q=r", "s": "t"}
